import{_ as e,a as t,b as o,c as r,d as n,e as d}from"./chunks/ee-ohos-12.DprJisAV.js";import{_ as s,o as c,c as i,a3 as l}from"./chunks/framework.BveOjhN0.js";const w=JSON.parse('{"title":"App on HarmonyOS","description":"","frontmatter":{"title":"App on HarmonyOS"},"headers":[],"relativePath":"050.openharmony/02.hap.md","filePath":"050.openharmony/02.hap.md","lastUpdated":1782647142000}'),p={name:"050.openharmony/02.hap.md"};function f(m,a,g,u,h,v){return c(),i("div",null,[...a[0]||(a[0]=[l('<div class="hero" data-v-0072f0cd><div class="hero-badges" data-v-0072f0cd><span class="badge badge--star" data-v-0072f0cd>⭐ 8000+ Star</span><span class="badge badge--version" data-v-0072f0cd>🚀 v5</span><span class="badge badge--ohos" data-v-0072f0cd>🪶 HarmonyOS</span></div><h1 class="hero-title" data-v-0072f0cd>ElectronEgg: v5 Upgrade — Easily Build HarmonyOS Apps</h1><div class="hero-actions" data-v-0072f0cd><a class="btn btn--primary" href="https://github.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-0072f0cd>GitHub Repo →</a><a class="btn btn--ghost" href="#wrapping-up" data-v-0072f0cd>Join Community</a></div></div><blockquote data-v-0072f0cd><p data-v-0072f0cd>One codebase, packaged for Windows, Mac, and Linux — and now it runs directly on HarmonyOS. ElectronEgg v5 brings HarmonyOS support.</p></blockquote><h2 id="introduction" tabindex="-1" data-v-0072f0cd>Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;" data-v-0072f0cd>​</a></h2><p data-v-0072f0cd>Since it was open-sourced, <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-0072f0cd>ElectronEgg</a>&#39;s vision has stayed simple: <strong data-v-0072f0cd>empower every developer to master desktop software development</strong>. It brings front-end and back-end engineering practices into desktop development, wrapping Electron&#39;s complexity behind a clean controller / service / preload layered architecture. The framework has now amassed <strong data-v-0072f0cd>8000+ Stars</strong> across the web, validated by long-term use across many teams — you can use it with confidence.</p><p data-v-0072f0cd>Building on this, v5 delivers a major upgrade — and one of its headline capabilities is: <strong data-v-0072f0cd>effortlessly build HarmonyOS apps</strong>.</p><p data-v-0072f0cd>After repeated attempts, we finally got ElectronEgg running on HarmonyOS devices. It&#39;s still in the <strong data-v-0072f0cd>testing phase</strong>, but the entire workflow already works end to end — see the screenshots below.</p><h2 id="harmonyos-support-one-codebase-running-on-harmonyos" tabindex="-1" data-v-0072f0cd>HarmonyOS Support: One Codebase, Running on HarmonyOS <a class="header-anchor" href="#harmonyos-support-one-codebase-running-on-harmonyos" aria-label="Permalink to &quot;HarmonyOS Support: One Codebase, Running on HarmonyOS&quot;" data-v-0072f0cd>​</a></h2><p data-v-0072f0cd>In the past, porting an Electron app to HarmonyOS essentially meant &quot;rewriting it from scratch&quot;. v5 automatically extracts your build artifacts and copies them into the HarmonyOS HAP resource directory, where they are loaded by the HAP project&#39;s web engine. <strong data-v-0072f0cd>Your existing ElectronEgg business code runs as a HarmonyOS app with almost no changes.</strong></p><p data-v-0072f0cd>Below are real screenshots of the ElectronEgg demo app running on HarmonyOS:</p><blockquote data-v-0072f0cd><p data-v-0072f0cd>App installed on the HarmonyOS system</p></blockquote><p data-v-0072f0cd><img src="'+e+'" alt="ElectronEgg demo in the HarmonyOS AppCenter" data-v-0072f0cd></p><blockquote data-v-0072f0cd><p data-v-0072f0cd>App launching</p></blockquote><p data-v-0072f0cd><img src="'+t+'" alt="ElectronEgg demo launching" data-v-0072f0cd></p><blockquote data-v-0072f0cd><p data-v-0072f0cd>Framework feature demo: communication, controllers, services and other capabilities work normally on HarmonyOS</p></blockquote><p data-v-0072f0cd><img src="'+o+'" alt="ElectronEgg demo feature showcase" data-v-0072f0cd></p><blockquote data-v-0072f0cd><p data-v-0072f0cd>Local image loading demo</p></blockquote><p data-v-0072f0cd><img src="'+r+'" alt="ElectronEgg demo feature showcase" data-v-0072f0cd></p><blockquote data-v-0072f0cd><p data-v-0072f0cd>Dock bar demo</p></blockquote><p data-v-0072f0cd><img src="'+n+'" alt="ElectronEgg demo feature showcase" data-v-0072f0cd></p><blockquote data-v-0072f0cd><p data-v-0072f0cd>Web page loading demo</p></blockquote><p data-v-0072f0cd><img src="'+d+'" alt="ElectronEgg demo feature showcase" data-v-0072f0cd></p><p data-v-0072f0cd>As you can see, a desktop app originally built for Windows / Mac runs smoothly on HarmonyOS — from installation to every feature. That&#39;s the core message of v5&#39;s HarmonyOS support: <strong data-v-0072f0cd>cross-platform is no longer a slogan; HarmonyOS is a first-class citizen.</strong></p><h2 id="what-else-is-new-in-v5" tabindex="-1" data-v-0072f0cd>What Else Is New in v5 <a class="header-anchor" href="#what-else-is-new-in-v5" aria-label="Permalink to &quot;What Else Is New in v5&quot;" data-v-0072f0cd>​</a></h2><p data-v-0072f0cd>Beyond HarmonyOS support, v5 also gives the framework core a fairly thorough refactor:</p><ul data-v-0072f0cd><li data-v-0072f0cd>Full TypeScript refactor: every API now has complete type definitions.</li><li data-v-0072f0cd>Dual module output: supports both CJS and ESM formats.</li><li data-v-0072f0cd>Pino logging: a more powerful logging system.</li><li data-v-0072f0cd>Bundle registry: faster startup.</li><li data-v-0072f0cd>Main-process bundling: main-process code can be bundled just like front-end code.</li><li data-v-0072f0cd>Build config overhaul: many fine-grained control options added.</li><li data-v-0072f0cd>Encryption upgrade: more secure.</li><li data-v-0072f0cd>ee-bin overhaul: now ships a complete TypeScript type system.</li></ul><h2 id="who-is-it-for" tabindex="-1" data-v-0072f0cd>Who Is It For <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who Is It For&quot;" data-v-0072f0cd>​</a></h2><ul data-v-0072f0cd><li data-v-0072f0cd>Developers who want to build desktop software with a front-end stack (Vue / React / HTML)</li><li data-v-0072f0cd>Teams that need to ship internal tools, admin consoles, or office software as desktop apps</li><li data-v-0072f0cd>Products that must cover Windows, Mac, Linux, <strong data-v-0072f0cd>and HarmonyOS</strong></li><li data-v-0072f0cd>Teams looking to lower Electron&#39;s learning curve and want a clear architecture</li></ul><p data-v-0072f0cd>Whether you&#39;re a front-end, back-end, ops, or client developer, you can get started quickly.</p><h2 id="wrapping-up" tabindex="-1" data-v-0072f0cd>Wrapping Up <a class="header-anchor" href="#wrapping-up" aria-label="Permalink to &quot;Wrapping Up&quot;" data-v-0072f0cd>​</a></h2><p data-v-0072f0cd>Desktop software — office tools, personal utilities — will remain a real, lasting need on the PC for the next decade. ElectronEgg exists to make building it simple, and now that simplicity extends to HarmonyOS.</p><p data-v-0072f0cd>The framework is already widely used in clients for accounting, government, enterprise, healthcare, education, stock trading, ERP, entertainment, video and more — feel free to use it with confidence.</p><div class="tip custom-block" data-v-0072f0cd><p class="custom-block-title" data-v-0072f0cd>Open Source &amp; Community</p><ul data-v-0072f0cd><li data-v-0072f0cd>GitHub: <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-0072f0cd>https://github.com/dromara/electron-egg</a></li><li data-v-0072f0cd>Gitee: <a href="https://gitee.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-0072f0cd>https://gitee.com/dromara/electron-egg</a></li></ul></div><p data-v-0072f0cd>If it helps you, a Star is appreciated — and come join the community to chat.</p>',33)])])}const k=s(p,[["render",f],["__scopeId","data-v-0072f0cd"]]);export{w as __pageData,k as default};
